import 'package:cloud_firestore/cloud_firestore.dart';import 'package:driver/view/delivery_boy_management/delivery_boy_list.dart';import 'package:driver/widgets/app_tost.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';class FireabaseDeliveryBoyController{  static final _auth = FirebaseAuth.instance;  static final _firestore = FirebaseFirestore.instance;    //add new delivery  static Future<bool> addDeliveryBoy({required BuildContext context, required Map<String, dynamic> data})async{    try{        int id = DateTime.now().millisecondsSinceEpoch;      await _firestore.collection("delivery_boys").doc(_auth.currentUser!.uid+id.toString()).set(data).then((value) {        AppToast.showToast("New Delivery boy added.", Colors.green);        Navigator.push(context, MaterialPageRoute(builder: (context)=>AllDeliveryBoy()));      });      return true;    }catch(e){      return false;    }  }    }